// O(1) Constant Time:
function getFirst(arr: number[]) {
  return arr[0]; // Instant index lookup
}

// O(N) Linear Time:
function findSum(arr: number[]) {
  let sum = 0;
  for (let i = 0; i < arr.length; i++) sum += arr[i]; // Single loop
  return sum;
}

// O(N^2) Quadratic Time:
function printPairs(arr: number[]) {
  for (let i = 0; i < arr.length; i++) {
    for (let j = 0; j < arr.length; j++) { // Nested loops
      console.log(arr[i], arr[j]);
    }
  }
}

