export function twoSum(nums: number[], target: number): number[] {
  const map = new Map<number, number>(); // Stores value -> index

  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (map.has(complement)) {
      return [map.get(complement)!, i]; // O(1) Lookup!
    }
    map.set(nums[i], i);
  }
  return [];
}

const duplicates = [1, 2, 2, 3, 4, 4, 5];

// Fast linear O(N) array deduplication!
const uniqueItems = [...new Set(duplicates)]; // [1, 2, 3, 4, 5]

// Fast O(1) membership check vs O(N) array.includes
const seenSet = new Set(uniqueItems);
console.log(seenSet.has(3)); // true (O(1))

export function twoSumSorted(numbers: number[], target: number): number[] {
  let left = 0;
  let right = numbers.length - 1;

  while (left < right) {
    const sum = numbers[left] + numbers[right];
    if (sum === target) return [left + 1, right + 1]; // Found!
    else if (sum < target) left++; // Need larger sum, move left rightward
    else right--; // Need smaller sum, move right leftward
  }
  return [];
}

export function lengthOfLongestSubstring(s: string): number {
  const seen = new Set<string>();
  let left = 0;
  let maxLength = 0;

  for (let right = 0; right < s.length; right++) {
    // Shrink window from left if duplicate character found
    while (seen.has(s[right])) {
      seen.delete(s[left]);
      left++;
    }
    seen.add(s[right]);
    maxLength = Math.max(maxLength, right - left + 1);
  }
  return maxLength;
}

async function slidingWindowRateLimit(ip) {
  const key = `ratelimit:sliding:${ip}`;
  const now = Date.now();
  const windowMs = 60000; // 1-minute rolling window
  const clearBefore = now - windowMs;

  // 1. Remove timestamps older than rolling window
  await redis.zremrangebyscore(key, 0, clearBefore);

  // 2. Count requests in current rolling window
  const count = await redis.zcard(key);

  if (count >= 100) {
    return { allowed: false }; // Exceeded limit!
  }

  // 3. Add current timestamp to ZSET
  await redis.zadd(key, now, `${now}-${Math.random()}`);
  await redis.expire(key, 60);

  return { allowed: true };
}

export function isValidParentheses(s: string): boolean {
  const stack: string[] = [];
  const map: Record<string, string> = { ')': '(', '}': '{', ']': '[' };

  for (const char of s) {
    if (char in map) {
      // Popped top must match opening bracket pair
      if (stack.pop() !== map[char]) return false;
    } else {
      stack.push(char); // Push opening bracket
    }
  }
  return stack.length === 0; // Stack must be empty if valid!
}

class ListNode {
  val: number; next: ListNode | null = null;
  constructor(val: number) { this.val = val; }
}

export function reverseList(head: ListNode | null): ListNode | null {
  let prev: ListNode | null = null;
  let current: ListNode | null = head;

  while (current !== null) {
    const nextTemp = current.next; // Store next node pointer
    current.next = prev;           // Reverse pointer!
    prev = current;
    current = nextTemp;
  }
  return prev; // New head of reversed list
}

export function binarySearch(nums: number[], target: number): number {
  let left = 0;
  let right = nums.length - 1;

  while (left <= right) {
    // Overflow-safe midpoint calculation
    const mid = left + Math.floor((right - left) / 2);

    if (nums[mid] === target) return mid;
    else if (nums[mid] < target) left = mid + 1;
    else right = mid - 1;
  }
  return -1; // Target not found
}

const memo = new Map<number, number>();

export function fib(n: number): number {
  if (n <= 1) return n; // Base Cases: fib(0)=0, fib(1)=1
  if (memo.has(n)) return memo.get(n)!; // Cache Hit!

  // Recursive step with memoization caching
  const result = fib(n - 1) + fib(n - 2);
  memo.set(n, result);
  return result;
}

class TreeNode {
  val: number;
  left: TreeNode | null = null;
  right: TreeNode | null = null;
  constructor(val: number) { this.val = val; }
}

// In-Order Traversal (Left -> Root -> Right) yields sorted array for BST!
export function inOrderTraversal(root: TreeNode | null, result: number[] = []): number[] {
  if (root === null) return result;
  inOrderTraversal(root.left, result);
  result.push(root.val); // Process root
  inOrderTraversal(root.right, result);
  return result;
}

export function levelOrder(root: TreeNode | null): number[][] {
  if (!root) return [];
  const result: number[][] = [];
  const queue: TreeNode[] = [root]; // Queue initialized with root

  while (queue.length > 0) {
    const levelSize = queue.length;
    const currentLevel: number[] = [];

    for (let i = 0; i < levelSize; i++) {
      const node = queue.shift()!; // Dequeue FIFO
      currentLevel.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    result.push(currentLevel);
  }
  return result;
}

export function numIslands(grid: string[][]): number {
  if (!grid || grid.length === 0) return 0;
  let count = 0;

  function dfs(r: number, c: number) {
    // Base Cases: Out of bounds or water ('0')
    if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] === '0') return;
    grid[r][c] = '0'; // Mark visited in-place!
    dfs(r + 1, c); dfs(r - 1, c); dfs(r, c + 1); dfs(r, c - 1); // Explore 4 directions
  }

  for (let r = 0; r < grid.length; r++) {
    for (let c = 0; c < grid[0].length; c++) {
      if (grid[r][c] === '1') {
        count++;
        dfs(r, c); // Sink connected island via DFS!
      }
    }
  }
  return count;
}

export function mergeSort(arr: number[]): number[] {
  if (arr.length <= 1) return arr;
  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid));
  const right = mergeSort(arr.slice(mid));
  return merge(left, right);
}

function merge(left: number[], right: number[]): number[] {
  const result: number[] = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) result.push(left[i++]);
    else result.push(right[j++]);
  }
  return result.concat(left.slice(i)).concat(right.slice(j));
}

export class MinHeap {
  private heap: number[] = [];

  peek(): number | null { return this.heap.length > 0 ? this.heap[0] : null; }

  insert(val: number): void {
    this.heap.push(val);
    this.bubbleUp(this.heap.length - 1); // Rebalance up
  }

  extractMin(): number | null {
    if (this.heap.length === 0) return null;
    const min = this.heap[0];
    const last = this.heap.pop()!;
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this.bubbleDown(0); // Rebalance down
    }
    return min;
  }

  private bubbleUp(i: number) {
    while (i > 0) {
      const p = Math.floor((i - 1) / 2);
      if (this.heap[i] >= this.heap[p]) break;
      [this.heap[i], this.heap[p]] = [this.heap[p], this.heap[i]];
      i = p;
    }
  }
  private bubbleDown(i: number) { /* Sift down logic */ }
}

export class Graph {
  private adjList = new Map<string, string[]>();

  addVertex(v: string) {
    if (!this.adjList.has(v)) this.adjList.set(v, []);
  }

  addEdge(v1: string, v2: string) {
    this.addVertex(v1);
    this.addVertex(v2);
    this.adjList.get(v1)!.push(v2); // Add edge v1 -> v2
    this.adjList.get(v2)!.push(v1); // Add edge v2 -> v1 (Undirected!)
  }

  getNeighbors(v: string): string[] {
    return this.adjList.get(v) || [];
  }
}
